// The one place the site reads Markdown articles from.
// Source files: content/articles/<slug>.md (see docs/publishing.md).
// The compiled data is generated by lib/publishing/compile.mjs whenever Next.js starts or builds.
import manifest from './.generated/articles.json'

import type { Category, Post } from '@/sanity/types'

type CompiledArticle = { post: Post; markdown: string; sourceFile: string }
type ArticleManifest = { articles: CompiledArticle[]; categories: Category[] }

const compiled = manifest as unknown as ArticleManifest

/** Every article that should appear on the site, newest first. */
export const FILE_ARTICLES: Post[] = compiled.articles.map((article) => article.post)

/** Categories listed in content/categories.yml. */
export const FILE_CATEGORIES: Category[] = compiled.categories

export function getFileArticle(slug: string): Post | null {
  return compiled.articles.find((article) => article.post.slug === slug)?.post ?? null
}

/** The plain-Markdown copy of an article for AI agents (served at /blog/<slug>.md). */
export function getFileArticleMarkdown(slug: string): string | null {
  return compiled.articles.find((article) => article.post.slug === slug)?.markdown ?? null
}

/** Article cards without bodies, small enough to send to the browser. */
export function getFileArticleCards(): Post[] {
  return FILE_ARTICLES.map(({ body: _body, ...card }) => card)
}
